#!/usr/bin/env bash
#
# Build the AAC-LC WASM audio decoder from aac_decode.cpp.
#
# Same Emscripten setup as the other codecs here (plugins/vp6/build.sh documents it):
# the machine's `python` is a Microsoft Store stub, so emcc is driven through the
# emsdk-bundled interpreter, and emcc gets Windows-form (D:/...) paths.
#
# -fno-strict-aliasing is REQUIRED: the escape codebook writes float coefficients through
# a uint32_t pointer, as FFmpeg does. -fwrapv: the scalefactor sums and the PNS generator
# rely on two's-complement wrap, as FFmpeg does.
#
# aac_tables.h is generated by extract_tables.mjs and committed; no FFmpeg tree is needed
# to build.
#
# Outputs:
#   ./aac_decode.{mjs,wasm}                 shipped decoder (web,worker)
#   ../../tests/wasm/aac_codec.{mjs,wasm}   node build for the vitest conformance test
#
# Usage:
#   ./build.sh            # speed build (-O3)
#   OPT=-Oz ./build.sh    # size build
#
set -euo pipefail

HERE_W="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -W)"
EMSDK_DIR="${EMSDK_DIR:-/d/dev/tools/emsdk}"
OPT="${OPT:--O3}"
LINK_OPT="${LINK_OPT:--O3}"

EMSDK_W="$(cd "$EMSDK_DIR" && pwd -W)"
PYBIN="$(ls "$EMSDK_DIR"/python/*/python.exe | head -1)"
export EM_CONFIG="$EMSDK_W/.emscripten"
export EMSDK_PYTHON="$(cd "$(dirname "$PYBIN")" && pwd -W)/python.exe"
EMCC="$EMSDK_W/upstream/emscripten/emcc.py"
emcc() { "$PYBIN" "$EMCC" "$@"; }

SRC="$HERE_W/aac_decode.cpp"
OBJ="$HERE_W/aac_decode.o"

echo "compiling aac ($OPT)..."
emcc $OPT -fwrapv -fno-strict-aliasing -ffunction-sections -fdata-sections -fno-exceptions -fno-rtti -c "$SRC" -o "$OBJ"

EXPORTS=_aac_open,_aac_close,_aac_reset,_aac_configure,_aac_decode_frame,_aac_channel_ptr,_aac_test_imdct,_malloc,_free

LINK_COMMON=( $LINK_OPT -Wl,--gc-sections -sMALLOC=emmalloc -sFILESYSTEM=0
              -sALLOW_MEMORY_GROWTH=1
              -sMODULARIZE=1 -sEXPORT_ES6=1
              -sEXPORTED_RUNTIME_METHODS=HEAPU8,HEAPU32,HEAPF32 --no-entry )

echo "=== link: shipped decoder (web,worker) ==="
emcc "${LINK_COMMON[@]}" -sENVIRONMENT=web,worker -sEXPORT_NAME=AacDecodeModule \
	-sEXPORTED_FUNCTIONS=$EXPORTS "$OBJ" -o "$HERE_W/aac_decode.mjs"

TESTDIR_W="$(cd "$HERE_W/../../tests" && pwd -W)/wasm"
mkdir -p "$TESTDIR_W"
echo "=== link: node test build ==="
emcc "${LINK_COMMON[@]}" -sENVIRONMENT=web,worker,node -sEXPORT_NAME=AacCodecModule \
	-sEXPORTED_FUNCTIONS=$EXPORTS "$OBJ" -o "$TESTDIR_W/aac_codec.mjs"

echo "BUILD_OK"
ls -la "$HERE_W"/aac_decode.wasm "$TESTDIR_W"/aac_codec.wasm
